// CONFIDENCE: MEDIUM. Read in full (170 lines). Prunes expired ignores and reschedules one timer for the next expiry.
UWorld* World = GetWorld();
if (World != nullptr)
{
	float MinRemaining = FLT_MAX;
	for (int32 i = IgnoredActors.Num() - 1; i >= 0; --i)
	{
		FIgnoredActorEntry& Entry = IgnoredActors[i];
		const float Elapsed = World->TimeSeconds - Entry.StartTime;   // +0x540
		if (Elapsed < Entry.RemainingAtStart)
		{
			float Remaining = FMath::Max(Entry.RemainingAtStart - Elapsed, 0.01f);
			MinRemaining = FMath::Min(MinRemaining, Remaining);
		}
		else
		{
			if (Entry.Actor != nullptr)
			{
				IgnoreComponent->SetIgnoredActor(Entry.Actor, false);   // FUN_1440f4040 remove
			}
			IgnoredActors.RemoveAtSwap(i);   // memmove + TArray16_ShrinkIfSparse
		}
	}
	if (MinRemaining >= FLT_MAX - 1e-8f)   // no live entries
	{
		if (TimerManager.IsTimerActive(ExpiryTimerHandle))   // FUN_144621fb0
		{
			TimerManager.ClearTimer(ExpiryTimerHandle);   // FTimerManager_InternalClearTimer
		}
		ExpiryTimerHandle = 0;
		return;
	}
	FTimerDelegate Delegate = BindUObject(this, &AFortPlayerPawn::RefreshIgnoredActors);   // FUN_142ee3b30 weak bind, FUN_142347f20 as callback
	TimerManager.SetTimer(ExpiryTimerHandle, Delegate, MinRemaining, false);   // FUN_1446278d0 (unread)
}
